def process(data):
    if not data:
        return {}

    positives = [x for x in data if x > 0]

    if not positives:
        return {"count": 0, "mean": 0, "min": 0, "max": 0}

    return {
        "count": len(positives),
        "mean": sum(positives) / len(positives),
        "min": min(positives),
        "max": max(positives),
    }

